import {familyOf,FAMILY_POLICY} from './narrative-family.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const label=s=>s[0].toUpperCase()+s.slice(1).replaceAll('-',' ');
function originHTML(o){return `<details><summary>Family/claim source</summary><p>Turn ${o.turn} · ${esc(o.source.setup?'Explicit pre-campaign record':o.source.incidentId+' · '+o.source.actionType)}</p><p>${esc(o.reason)}</p></details>`;}
export function familyHTML(state,c){return `<h4>Family</h4><ul>${familyOf(state,c.id).map(f=>`<li>${esc(f.tie)}: ${esc(state.narrative.characters[f.id].name)}${f.derived?' (shared recorded parent)'+f.sources.map(originHTML).join(''):f.link?originHTML(f.link.origin)+(f.link.end?originHTML(f.link.end):''):''}</li>`).join('')||'<li>No family ties recorded.</li>'}</ul>`;}
function supportHTML(state,k){const links=(k.support?.familyLinkIds||[]).map(id=>state.narrative.familyLinks.find(l=>l.id===id)),claims=(k.support?.claimIds||[]).map(id=>state.narrative.claimsV2.find(c=>c.id===id));return links.length||claims.length?`<details><summary>Claim basis evidence</summary><ul>${links.map(l=>`<li>${esc(l.id)}: ${label(l.type)} · ${esc(state.narrative.characters[l.fromId].name)} → ${esc(state.narrative.characters[l.toId].name)}</li>`).join('')}${claims.map(c=>`<li>${esc(c.id)}: ${esc(state.narrative.characters[c.claimantId].name)} · ${esc(label(c.region))} · ${label(c.basis)}</li>`).join('')}</ul></details>`:'';}
export function claimsHTML(state,c){const claims=(state.narrative.claimsV2||[]).filter(k=>k.claimantId===c.id),legacy=c.claims.filter(region=>!claims.some(k=>k.region===region));return `<h4>Claims</h4><p>${legacy.map(label).join(', ')||(!claims.length?'None recorded.':'')}</p>${claims.length?`<p class="small-note">Recorded dynastic interests; no automatic inheritance or board-game effect.</p><ul class="dynastic-claims">${claims.map(k=>`<li><b>${esc(label(k.region))} · ${label(k.basis)} · ${label(k.status)}</b><p>${label(k.standing)}${c.age<FAMILY_POLICY.adultAge?' · Child: any future accession needs an eligible regent.':''}</p>${originHTML(k.origin)}${supportHTML(state,k)}${k.statusHistory?.length?`<details><summary>Claim status history</summary>${k.statusHistory.map(h=>`<p>${label(h.from)} → ${label(h.to)}</p>${originHTML(h.origin)}`).join('')}</details>`:''}</li>`).join('')}</ul>`:''}`;}
export function affiliationsHTML(state,c){const rows=c.dynastyAffiliations||[],identity=c.gender?`<p>Recorded gender: ${label(c.gender.value)}</p>${originHTML(c.gender.origin)}`:'';return identity+(rows.length?`<section><h4>Recorded house affiliations</h4><ul>${rows.map(a=>`<li>${label(a.kind)}: ${esc(state.narrative.dynasties[a.dynastyId].name)}${a.end?' (ended)':''}${originHTML(a.origin)}${a.end?originHTML(a.end):''}</li>`).join('')}</ul></section>`:'');}
